def unary_op(op) do
  cond do
    op in [:&, :...] -> {:non_associative, 90}
    op in [:!, :^, :not, :+, :-, :"~~~"] -> {:non_associative, 300}
    op in [:@] -> {:non_associative, 320}
    true -> :error
  end
end

def spec_to_quoted(name, spec)
def spec_to_quoted(name, {:type, anno, :fun, [{:type, _, :product, args}, result]})
    when is_atom(name) do
  meta = meta(anno)
  body = {name, meta, Enum.map(args, &typespec_to_quoted/1)}

  vars =
    for type_expr <- args ++ [result],
        var <- collect_vars(type_expr),
        uniq: true,
        do: {var, {:var, meta, nil}}

  spec = {:"::", meta, [body, typespec_to_quoted(result)]}

  if vars == [] do
    spec
  else
    {:when, meta, [spec, vars]}
  end
end
def spec_to_quoted(name, {:type, anno, :fun, []}) when is_atom(name) do
  meta = meta(anno)

  {:"::", meta,
   [
     {name, meta, []},
     quote do
       term
     end
   ]}
end
def spec_to_quoted(name, {:type, anno, :bounded_fun, [type, constrs]}) when is_atom(name) do
  meta = meta(anno)
  {:type, _, :fun, [{:type, _, :product, args}, result]} = type

  guards =
    for {:type, _, :constraint, [{:atom, _, :is_subtype}, [{:var, _, var}, type]]} <- constrs do
      {erl_to_ex_var(var), typespec_to_quoted(type)}
    end

  ignore_vars = Keyword.keys(guards)

  vars =
    for type_expr <- args ++ [result],
        var <- collect_vars(type_expr),
        var not in ignore_vars,
        uniq: true,
        do: {var, {:var, meta, nil}}

  args =
    for arg <- args do
      typespec_to_quoted(arg)
    end

  when_args = [{:"::", meta, [{name, meta, args}, typespec_to_quoted(result)]}, guards ++ vars]
  {:when, meta, when_args}
end

def request(operation, _) do
  :timer.sleep(40)
  send(self(), {operation.action, operation.params})

  case operation.action do
    :publish ->
      {:ok, %{body: %{message_id: "123", request_id: "345"}}}

    :check_if_phone_number_is_opted_out ->
      case operation.params["phoneNumber"] do
        "+18675309" -> {:ok, %{body: %{is_opted_out: true}}}
        "+1816613" -> {:error, :mock}
        _ -> {:ok, %{body: %{is_opted_out: false}}}
      end

    :opt_in_phone_number ->
      {:ok, %{body: %{request_id: "345"}}}

    _ ->
      {:error, operation}
  end
end

